// Demo intake — one item per till-log row. The demo data is a
// realistic dirty batch: history rows first (two prior over-band
// nights for Nga set up the escalation), then today's entries.
//
// In production this whole lane is replaced by the two Sheet reads
// below — enable them and remove this node. The Reconcile node
// splits today from history by max date, so no extra flag field
// is needed in either lane.
return [
  // --- prior-30-day history (production: the 'till log' Sheet) ---
  { json: { date: '2026-09-25', shift: 'day',   staff: 'Linh', expected_sales: 2100.00, counted_cash: 2098.00 } },
  { json: { date: '2026-09-26', shift: 'night', staff: 'Nga',  expected_sales: 1400.00, counted_cash: 1280.00 } },
  { json: { date: '2026-09-27', shift: 'day',   staff: 'Linh', expected_sales: 1900.00, counted_cash: 1901.50 } },
  { json: { date: '2026-09-27', shift: 'night', staff: 'Nga',  expected_sales: 1350.00, counted_cash: 1200.00 } },
  // --- today's submissions (max date in the batch = today) ---
  { json: { date: '2026-10-01', shift: 'day',   staff: 'Linh', expected_sales: 2050.00, counted_cash: 2048.40 } },
  { json: { date: '2026-10-01', shift: 'night', staff: 'Nga',  expected_sales: 1600.00, counted_cash: 1420.00 } },
  { json: { date: '2026-10-01', shift: 'night', staff: 'Nga',  expected_sales: 1600.00, counted_cash: 1421.00 } },
  { json: { date: '2026-10-01', shift: 'day',   staff: 'Bo',   expected_sales:  900.00 } }
  // no entry at all for 09-28, 09-29, 09-30 -> submission gap
];

// Cash Leak Watchdog — reconcile today's till, detect gaps,
// quarantine bad rows, and escalate repeated shortfalls by the
// same staff/shift. Today = the max submitted date, so the same
// code serves the demo lane and the Sheet lane unchanged.
//
// RULES — edit to match your shop's policy.
const RULES = {
  tolerance_abs: 5.00,   // currency units always tolerated
  tolerance_pct: 0.5,    // % of expected sales — band widens on big days
  currency: '$',
  escalate_after: 2,     // prior over-band shifts by same staff -> escalation
  history_days: 30
};

const MS_PER_DAY = 86400000;
const toDay = d => Date.parse(d + 'T00:00:00Z');
const toISO = ms => new Date(ms).toISOString().slice(0, 10);
const money = n => `${RULES.currency}${Math.abs(n).toFixed(2)}`;

const rows = $input.all().map(i => i.json);
const isComplete = r =>
  r.date && typeof r.expected_sales === 'number' && typeof r.counted_cash === 'number';

const complete = rows.filter(isComplete);
const malformed = rows.filter(r => !isComplete(r));

// Split today vs history by max date — no scope flag needed.
const today = complete.length
  ? toISO(Math.max(...complete.map(r => toDay(r.date))))
  : null;
const history = complete.filter(r => r.date !== today);
const todays = complete.filter(r => r.date === today);

const out = [];
const alerts = [];

// Prior over-band shifts per staff member — the state that makes a
// single variance turn into an escalation.
const priorOverBand = {};
let leak30d = 0;
for (const h of history) {
  const delta = Math.round((h.counted_cash - h.expected_sales) * 100) / 100;
  const band = Math.max(RULES.tolerance_abs, h.expected_sales * RULES.tolerance_pct / 100);
  if (Math.abs(delta) > band) {
    priorOverBand[h.staff] = (priorOverBand[h.staff] || 0) + 1;
    leak30d += delta;
  }
}

// Malformed rows are parked — they reach the owner as data-quality
// alerts and reprocess automatically once fixed, since production
// intake re-reads the whole log each sweep.
for (const r of malformed) {
  const missing = !r.date ? 'date'
    : typeof r.expected_sales !== 'number' ? 'expected_sales' : 'counted_cash';
  const alert = `Till check ${r.date || '(no date)'} ${r.shift || ''} quarantined: missing required field '${missing}' — row parked for reprocess`;
  out.push({ json: { status: 'alerted', route: 'quarantine', kind: 'missing-data',
    ...r, flag: `missing ${missing}`, alert } });
  alerts.push(alert);
}

// Submission gap: days between the last history date and today with
// no entry at all — a day nobody submitted is the worst kind of short.
if (history.length && today) {
  const lastHist = Math.max(...history.map(r => toDay(r.date)));
  const silent = Math.round((toDay(today) - lastHist) / MS_PER_DAY) - 1;
  if (silent > 0) {
    const first = toISO(lastHist + MS_PER_DAY);
    const last = toISO(toDay(today) - MS_PER_DAY);
    const alert = `No till submission for ${silent} day(s): ${first} to ${last} — check whether the shop was closed or entries were skipped`;
    out.push({ json: { status: 'alerted', route: 'alert', kind: 'missing-data',
      date: `${first}..${last}`, flag: 'submission gap', alert } });
    alerts.push(alert);
  }
}

// Today's entries: dedupe by date+shift, then band check, then
// repeat-offender escalation against the 30-day history.
const seen = new Set();
for (const r of todays) {
  const key = `${r.date}|${r.shift}`;
  const base = { date: r.date, shift: r.shift, staff: r.staff,
    expected_sales: r.expected_sales, counted_cash: r.counted_cash };

  if (seen.has(key)) {
    const alert = `Duplicate till entry for ${r.date} ${r.shift} (${r.staff}) — first submission kept, this one ignored`;
    out.push({ json: { status: 'alerted', route: 'quarantine', kind: 'duplicate',
      ...base, flag: 'duplicate submission', alert } });
    alerts.push(alert);
    continue;
  }
  seen.add(key);

  const delta = Math.round((r.counted_cash - r.expected_sales) * 100) / 100;
  const band = Math.round(Math.max(RULES.tolerance_abs, r.expected_sales * RULES.tolerance_pct / 100) * 100) / 100;

  if (Math.abs(delta) <= band) {
    out.push({ json: { status: 'logged', route: 'clean', ...base, delta, band,
      line: `${r.date} ${r.shift} (${r.staff}): delta ${delta >= 0 ? '+' : ''}${delta.toFixed(2)} within ±${band.toFixed(2)}` } });
    continue;
  }

  const priors = priorOverBand[r.staff] || 0;
  leak30d += delta;
  const over = delta < 0 ? 'short' : 'over';
  let alert, route;
  if (priors >= RULES.escalate_after) {
    route = 'escalation';
    alert = `ESCALATION: ${r.staff} ${over} ${money(delta)} on ${r.date} ${r.shift} — over-band shift #${priors + 1} in ${RULES.history_days} days. Review the till procedure for this shift`;
  } else {
    route = 'alert';
    alert = `Till check ${r.date} ${r.shift} (${r.staff}): ${over} ${money(delta)} — outside ±${money(band)} band${priors ? ` (prior over-band shifts: ${priors})` : ''}`;
  }
  out.push({ json: { status: 'alerted', route, kind: 'failure',
    ...base, delta, band, prior_offenses: priors, alert } });
  alerts.push(alert);
}

// One digest per run — computed here, after every branch verdict, so
// an empty branch can never starve it. The Switch routes it to the
// digest channel downstream.
const clean = out.filter(i => i.json.status === 'logged');
const topOffender = Object.entries(priorOverBand)
  .sort((a, b) => b[1] - a[1])[0];
out.push({ json: {
  status: 'digest',
  route: 'digest',
  channel: 'owner-digest',
  summary: `Run complete: ${clean.length} shift(s) reconciled clean, ${alerts.length} alert(s)`,
  leak_30d_total: Math.round(leak30d * 100) / 100,
  repeat_watch: topOffender ? `${topOffender[0]} (${topOffender[1]} prior over-band shifts)` : 'none',
  needs_attention: alerts
} });

return out;
